#[test]
fn composite_glyph_paints() {
    // 0xC4 = Ä — composite of A + dieresis dots.
    let r = render("text_composite_glyph.pdf").unwrap();
    assert!(ink_bbox(&r).is_some());
}

#[test]
fn differences_remap_code() {
    // Differences [65 /B 66 /A]: code 65 → glyph B, code 66 → glyph A.
    // Rendered output is "BA" — B then A — so the *first* glyph drawn
    // (leftmost) is B. Both glyphs are identical boxes in our font, so
    // instead verify via Poppler that the *shapes* differ. Here we
    // just verify the pipeline ran without error.
    let r = render("text_differences_encoding.pdf").unwrap();
    assert!(ink_bbox(&r).is_some());
}

#[test]
fn notdef_for_unencoded_code() {
    // Char 0x01 has no WinAnsi entry → .notdef (a box in our font).
    let r = render("text_notdef.pdf").unwrap();
    let (minx, _miny, _maxx, _maxy) = ink_bbox(&r).unwrap();
    // A at x=20, .notdef after it, Z last — total advance = 3×600×24/1000 = 43.2
    assert!(minx >= 20);
}

#[test]
fn mac_roman_encoding_renders() {
    // /MacRomanEncoding is a predefined table (Annex D) — the Latin
    // letters it shares with WinAnsi draw exactly as before.
    let r = render("text_unsupported_encoding.pdf").unwrap();
    assert!(ink_bbox(&r).is_some());
}

#[test]
fn symbolic_font_maps_codes_through_cmap() {
    // Symbolic flag set: codes go through the (3,0)/(1,0) cmap, or the
    // (3,1) cmap via StandardEncoding names when that is all the font
    // has (§9.6.6.4) — the glyphs draw rather than the page refusing.
    let r = render("text_symbolic_refused.pdf").unwrap();
    assert!(ink_bbox(&r).is_some());
}

#[test]
fn nonembedded_type1_renders_with_substitute_and_says_so() {
    // text_unsupported_type1.pdf: a Standard 14 font with no program.
    // It now draws with the bundled substitute — and the page reports
    // the substitution so nobody mistakes it for the real font.
    let r = render("text_unsupported_type1.pdf").unwrap();
    assert!(ink_bbox(&r).is_some(), "substitute drew no ink");
    assert!(
        !r.font_substitutions.is_empty(),
        "substitution must be reported"
    );
}

